#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll modpow(ll base, ll exp, ll mod){
    base %= mod;
    ll result = 1 % mod;
    while(exp > 0){
        if(exp & 1) result = (__int128)result * base % mod;
        base = (__int128)base * base % mod;
        exp >>= 1;
    }
    return result;
}

int main(){
    ll n;
    cin >> n;
    for(ll k = 1; ; k++){
        if(modpow(k, n, n) == 0){
            cout << k << "\n";
            return 0;
        }
    }
}
